Chapter.Code:
// -----------------------------------------------------------------------------
// A deliberately explicit CPU-side reference architecture.
// This is not meant to replace Maveb's optimized implementation; it shows the
// semantic pipeline from imported trained parameters to final pixel values.
// -----------------------------------------------------------------------------

struct Gaussian
{
    Vec3 position;

    // Trained parameterization. Keep these encoded in canonical asset state.
    Vec3 logScale;

    // Quaternion in the canonical (w,x,y,z) convention.
    Quat rotation;

    float opacityLogit;

    // Spherical-harmonic color coefficients.
    Vec3 shDC;
    std::array<float, 45> shRest;
    uint32_t shRestCount;

    // A production editable-world system should use persistent identity here.
    GaussianId stableId;
};

struct ProjectedGaussian
{
    Vec2 center;
    float depth;
    float radius;

    // The symmetric inverse covariance:
    //
    // [ A B ]
    // [ B C ]
    //
    float A;
    float B;
    float C;

    float opacity;
    Vec3 color;

    TileRect tiles;

    GaussianId stableId;
};

ProjectedGaussian projectGaussian(
    const Gaussian& g,
    const Camera& camera)
{
    // -------------------------------------------------------------------------
    // 1. Recover physical Gaussian scale.
    //
    // log-scale guarantees positive scales after exponential decoding.
    // -------------------------------------------------------------------------
    const Vec3 scale
    {
        std::exp(g.logScale.x),
        std::exp(g.logScale.y),
        std::exp(g.logScale.z)
    };

    // -------------------------------------------------------------------------
    // 2. Convert quaternion to an orthonormal 3×3 rotation.
    // -------------------------------------------------------------------------
    const Mat3 R =
        rotationMatrix(
            normalize(g.rotation));

    // -------------------------------------------------------------------------
    // 3. Build world covariance:
    //
    // Σw = R diag(s²) Rᵀ
    // -------------------------------------------------------------------------
    const Mat3 variance =
        diagonal(
            scale.x * scale.x,
            scale.y * scale.y,
            scale.z * scale.z);

    const Mat3 sigmaWorld =
        R *
        variance *
        transpose(R);

    // -------------------------------------------------------------------------
    // 4. Transform center into camera coordinates.
    // -------------------------------------------------------------------------
    const Vec3 p =
        transformPoint(
            camera.worldToCamera,
            g.position);

    if (p.z < camera.nearPlane ||
        p.z > camera.farPlane)
    {
        throw Culled{};
    }

    // -------------------------------------------------------------------------
    // 5. Perspective-project mean.
    // -------------------------------------------------------------------------
    ProjectedGaussian out;

    out.center.x =
        camera.fx * p.x / p.z
        + camera.cx;

    out.center.y =
        camera.fy * p.y / p.z
        + camera.cy;

    out.depth =
        p.z;

    // -------------------------------------------------------------------------
    // 6. Transform covariance into camera coordinates.
    //
    // Translation does not affect covariance.
    // -------------------------------------------------------------------------
    const Mat3 Rc =
        upper3x3(
            camera.worldToCamera);

    const Mat3 sigmaCamera =
        Rc *
        sigmaWorld *
        transpose(Rc);

    // -------------------------------------------------------------------------
    // 7. Derivative of perspective projection.
    // -------------------------------------------------------------------------
    const float invZ =
        1.0f / p.z;

    const Vec3 jx
    {
        camera.fx * invZ,
        0.0f,
        -camera.fx *
         p.x *
         invZ * invZ
    };

    const Vec3 jy
    {
        0.0f,
        camera.fy * invZ,
        -camera.fy *
         p.y *
         invZ * invZ
    };

    // -------------------------------------------------------------------------
    // 8. Σscreen = J Σcamera Jᵀ.
    // Add low-pass variance exactly as the Maveb path does.
    // -------------------------------------------------------------------------
    const float a =
        dot(
            jx,
            sigmaCamera * jx)
        + 0.3f;

    const float b =
        dot(
            jx,
            sigmaCamera * jy);

    const float c =
        dot(
            jy,
            sigmaCamera * jy)
        + 0.3f;

    const float det =
        a * c - b * b;

    if (!std::isfinite(det) ||
        det <= 1e-12f)
    {
        throw Culled{};
    }

    // -------------------------------------------------------------------------
    // 9. Invert 2×2 covariance to form conic.
    // -------------------------------------------------------------------------
    out.A =  c / det;
    out.B = -b / det;
    out.C =  a / det;

    // -------------------------------------------------------------------------
    // 10. Conservative three-sigma screen bound.
    // -------------------------------------------------------------------------
    const float discriminant =
        std::sqrt(
            std::max(
                0.0f,
                (a - c) * (a - c)
                + 4.0f * b * b));

    const float lambdaMax =
        0.5f *
        (a + c + discriminant);

    out.radius =
        3.0f *
        std::sqrt(lambdaMax);

    // -------------------------------------------------------------------------
    // 11. Decode opacity and SH appearance.
    // -------------------------------------------------------------------------
    out.opacity =
        sigmoid(
            g.opacityLogit);

    out.color =
        evaluateSH(
            g,
            normalize(
                g.position -
                camera.worldPosition));

    out.stableId =
        g.stableId;

    // -------------------------------------------------------------------------
    // 12. Screen and tile culling.
    // -------------------------------------------------------------------------
    const int minX =
        clamp(
            floor(out.center.x -
                  out.radius),
            0,
            camera.width - 1);

    const int maxX =
        clamp(
            ceil(out.center.x +
                 out.radius),
            0,
            camera.width - 1);

    const int minY =
        clamp(
            floor(out.center.y -
                  out.radius),
            0,
            camera.height - 1);

    const int maxY =
        clamp(
            ceil(out.center.y +
                 out.radius),
            0,
            camera.height - 1);

    if (minX > maxX ||
        minY > maxY)
    {
        throw Culled{};
    }

    constexpr int TileSize = 16;

    out.tiles.minX =
        minX / TileSize;

    out.tiles.maxX =
        maxX / TileSize;

    out.tiles.minY =
        minY / TileSize;

    out.tiles.maxY =
        maxY / TileSize;

    return out;
}

// First determine how many tile references every Gaussian emits.
for (uint32_t g = 0;
     g < projected.size();
     ++g)
{
    counts[g] =
        projected[g].tiles.width()
        *
        projected[g].tiles.height();
}

// Exclusive scan allocates each Gaussian a disjoint write interval.
offsets =
    exclusivePrefixSum(
        counts);

const uint32_t totalReferences =
    offsets.back()
    + counts.back();

keys.resize(totalReferences);
values.resize(totalReferences);

// Expand one projected Gaussian into every tile it overlaps.
for (uint32_t g = 0;
     g < projected.size();
     ++g)
{
    uint32_t dst =
        offsets[g];

    for (
        uint32_t ty =
            projected[g].tiles.minY;
        ty <=
            projected[g].tiles.maxY;
        ++ty)
    {
        for (
            uint32_t tx =
                projected[g].tiles.minX;
            tx <=
                projected[g].tiles.maxX;
            ++tx)
        {
            const uint32_t tileId =
                ty * tileColumns + tx;

            // The implementation may encode this in two uint32s,
            // but semantically the composite key is:
            //
            //      primary   = tile
            //      secondary = depth
            //
            keys[dst] =
                {
                    tileId,
                    projected[g].depth
                };

            values[dst] =
                g;

            ++dst;
        }
    }
}

// Stable order is required for deterministic equal-depth behavior.
stableSort(
    keys,
    values,
    [](const Key& a,
       const Key& b)
    {
        if (a.tile != b.tile)
            return a.tile <
                   b.tile;

        return a.depth <
               b.depth;
    });

for each tile:
    range[tile] =
        Empty;

for (
    uint32_t i = 0;
    i < keys.size();
    ++i)
{
    const uint32_t tile =
        keys[i].tile;

    if (range[tile].empty())
        range[tile].begin = i;

    range[tile].end =
        i + 1;
}

for (
    int y = 0;
    y < height;
    ++y)
{
    for (
        int x = 0;
        x < width;
        ++x)
    {
        const uint32_t tile =
            (y / 16) *
            tileColumns
            +
            (x / 16);

        Vec3 color{0.0f};
        float transmittance =
            1.0f;

        float firstDepth =
            infinity;

        GaussianId dominantId{};
        float dominantContribution =
            0.0f;

        for (
            uint32_t r =
                ranges[tile].begin;
            r <
                ranges[tile].end;
            ++r)
        {
            const ProjectedGaussian& g =
                projected[
                    values[r]];

            // Pixel centers, not integer corners.
            const float dx =
                (x + 0.5f)
                - g.center.x;

            const float dy =
                (y + 0.5f)
                - g.center.y;

            const float q =
                g.A * dx * dx
                +
                2.0f *
                g.B *
                dx * dy
                +
                g.C * dy * dy;

            // Three-sigma ellipse.
            if (q > 9.0f)
                continue;

            const float alpha =
                std::min(
                    0.99f,
                    g.opacity *
                    std::exp(
                        -0.5f * q));

            if (
                alpha <
                1.0f / 255.0f)
            {
                continue;
            }

            const float weight =
                transmittance
                * alpha;

            color +=
                weight *
                g.color;

            if (
                firstDepth ==
                infinity)
            {
                firstDepth =
                    g.depth;
            }

            if (
                weight >
                dominantContribution)
            {
                dominantContribution =
                    weight;

                dominantId =
                    g.stableId;
            }

            transmittance *=
                1.0f - alpha;

            // Error remaining behind this point is now bounded by
            // approximately 0.1% of the remaining color range.
            if (
                transmittance <
                0.001f)
            {
                break;
            }
        }

        color +=
            transmittance *
            background;

        output[x,y] =
            color;
    }
}

